# ---------------------------------------------------------------- font engine
class Font:
    """A vector font: outlines -> supersampled greyscale bitmaps, cached."""

    def __init__(self, name, slant=0.0):
        self.name = name
        self.slant = slant
        self._cache = {}

    def _flatten(self, contours, scale):
        """Outline contours -> list of polygons in pixel space (y down)."""
        polys = []
        for (sx, sy, segs) in contours:
            pts = [(sx * scale + self.slant * sy * scale, -sy * scale)]
            cx, cy = sx, sy
            for seg in segs:
                if seg[0] == "L":
                    _, x, y = seg
                    pts.append((x * scale + self.slant * y * scale, -y * scale))
                    cx, cy = x, y
                else:
                    _, qx, qy, x, y = seg
                    x0, y0 = cx, cy
                    # subdivide the quadratic so no step exceeds ~0.5 px
                    dist = ((x - x0) ** 2 + (y - y0) ** 2) ** 0.5 * scale
                    n = max(2, int(dist * 2) + 1)
                    for i in range(1, n + 1):
                        t = i / n
                        mt = 1.0 - t
                        px = mt * mt * x0 + 2 * mt * t * qx + t * t * x
                        py = mt * mt * y0 + 2 * mt * t * qy + t * t * y
                        pts.append((px * scale + self.slant * py * scale,
                                    -py * scale))
                    cx, cy = x, y
            if len(pts) >= 3:
                polys.append(pts)
        return polys

    def _rasterise(self, ch, size):
        """Return (width, height, xoff, yoff, alpha_bytes) for one glyph.

        xoff: pixels from pen x to bitmap left. yoff: pixels from the
        baseline UP to the bitmap top. Alpha is 0..255 greyscale.
        """
        adv, contours = GLYPHS[self.name][ch]
        scale = size / UPM
        ss = 4  # supersample factor
        polys = self._flatten(contours, scale * ss)
        xs = [p[0] for poly in polys for p in poly]
        ys = [p[1] for poly in polys for p in poly]
        min_x, max_x = min(xs), max(xs)
        min_y, max_y = min(ys), max(ys)
        bw = int(max_x - min_x + 0.5) + 2
        bh = int(max_y - min_y + 0.5) + 2
        ox = min_x - 1.0
        oy = min_y - 1.0
        # even-odd scanline fill on the supersampled grid
        grid = bytearray(bw * bh)
        edges = []
        for poly in polys:
            n = len(poly)
            for i in range(n):
                x0, y0 = poly[i]
                x1, y1 = poly[(i + 1) % n]
                if y0 == y1:
                    continue
                edges.append((y0, y1, x0, x1))
        for row in range(bh):
            yc = oy + row + 0.5
            spans = []
            for (y0, y1, x0, x1) in edges:
                if (y0 <= yc < y1) or (y1 <= yc < y0):
                    t = (yc - y0) / (y1 - y0)
                    spans.append(x0 + t * (x1 - x0))
            if not spans:
                continue
            spans.sort()
            for k in range(0, len(spans) - 1, 2):
                xa = int(spans[k] - ox)
                xb = int(spans[k + 1] - ox)
                if xb > xa:
                    base = row * bw + max(0, xa)
                    for xx in range(max(0, xa), min(bw, xb)):
                        grid[base + (xx - max(0, xa))] = 1
        # box-downsample ss x ss -> 8-bit alpha
        w_out = (bw + ss - 1) // ss
        h_out = (bh + ss - 1) // ss
        alpha = bytearray(w_out * h_out)
        for oy2 in range(h_out):
            for ox2 in range(w_out):
                tot = 0
                for dy in range(ss):
                    gy = oy2 * ss + dy
                    if gy >= bh:
                        break
                    base = gy * bw + ox2 * ss
                    for dx in range(ss):
                        gx = ox2 * ss + dx
                        if gx < bw:
                            tot += grid[base + dx]
                alpha[oy2 * w_out + ox2] = min(255, tot * 255 // (ss * ss))
        xoff = int(ox / ss)
        yoff = int(-oy / ss)
        return (w_out, h_out, xoff, yoff, bytes(alpha))

    def glyph(self, ch, size):
        key = (ch, size)
        g = self._cache.get(key)
        if g is None:
            g = self._rasterise(ch, size)
            self._cache[key] = g
        return g

    def width(self, text, size):
        scale = size / UPM
        tot = 0.0
        for ch in text:
            adv, _ = GLYPHS[self.name][ch]
            tot += adv * scale
        return tot

    def draw(self, cv, text, size, x, y_baseline, color, align="left"):
        """Draw text; (x, y_baseline) is the pen position (left-aligned)."""
        if align in ("center", "right"):
            w = self.width(text, size)
            if align == "center":
                x -= w / 2.0
            else:
                x -= w
        pen = x
        scale = size / UPM
        for ch in text:
            if ch == " ":
                adv, _ = GLYPHS[self.name][" "]
                pen += adv * scale
                continue
            bw, bh, xoff, yoff, alpha = self.glyph(ch, size)
            cv.blit_alpha(alpha, bw, bh, int(round(pen)) + xoff,
                          int(round(y_baseline)) - yoff, color)
            adv, _ = GLYPHS[self.name][ch]
            pen += adv * scale
        return pen


